import {portrait} from './portraits.js';
import {MAPS} from './maps.js';
const fmt=n=>Math.round(n).toLocaleString('zh-CN');
const categories=[['cash','现金','#e1b64e'],['deposit','存款','#65a58c'],['property','地产','#cb8464'],['stocks','股票','#75a6bb'],['vehicle','交通工具','#aa976b']];
export function settlement(g){const ranked=g.ranking();let place=1;return ranked.map((p,index)=>{if(index&&(p.alive!==ranked[index-1].alive||g.worth(p)!==g.worth(ranked[index-1])))place=index+1;return {player:p,rank:place,assets:g.assets(p),lots:g.owned(p).length,winner:place===1};});}
const trophy='<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M27 23H10v12q0 26 26 25M73 23h17v12q0 26-26 25" fill="none" stroke="#b18235" stroke-width="7"/><path d="M24 16h52v26q0 24-26 28Q24 66 24 42Z" fill="#f1c55b" stroke="#ab7935" stroke-width="3"/><path d="M33 23h7v20q0 12 7 17" fill="none" stroke="#ffed9f" stroke-width="5" stroke-linecap="round"/><path d="M45 69h10v14H45Z" fill="#c08d38"/><path d="M31 83h38v9H31Z" fill="#d7a146" stroke="#9b7032" stroke-width="2"/><path d="m50 29 4 8 9 1-7 6 2 9-8-5-8 5 2-9-7-6 9-1Z" fill="#fff2b6"/></svg>';
function assetDetails(row){const a=row.assets,gross=categories.reduce((sum,[key])=>sum+a[key],0);return `<div class="result-ledger"><div class="asset-ribbon" role="img" aria-label="总资产 ${fmt(gross)} 奶币，不含贷款扣除">${categories.filter(([key])=>a[key]>0).map(([key,label,color])=>`<span style="width:${a[key]/gross*100}%;background:${color}" title="${label} ${fmt(a[key])}"></span>`).join('')}</div><dl>${categories.map(([key,label,color])=>`<div><dt><i style="background:${color}"></i>${label}</dt><dd>${fmt(a[key])}</dd></div>`).join('')}<div class="result-loan"><dt>扣除贷款</dt><dd>−${fmt(a.loan)}</dd></div><div class="result-total"><dt>净资产</dt><dd>${fmt(a.total)}</dd></div></dl></div>`;}
export function resultsPanel(g){
 const rows=settlement(g),winners=rows.filter(r=>r.winner),champions=winners.map(r=>g.char(r.player).name).join('、'),human=rows.find(r=>r.player.human),alive=rows.filter(r=>r.player.alive),lead=winners.length===1&&alive.length>1?winners[0].assets.total-alive[1].assets.total:null;
 return `<div class="settlement"><section class="winner-banner"><div class="winner-trophy">${trophy}</div><div class="winner-faces">${winners.map(r=>`<span>${portrait(r.player.character)}</span>`).join('')}</div><h3>${champions}${winners.length>1?'并列夺冠':'夺冠！'}</h3><p>${alive.length===1?'坚持到最后，成为唯一存活奶伴':`完成 ${g.s.round} 轮旅行，按净资产结算`}</p><strong class="winner-score">${fmt(winners[0].assets.total)}<small> 奶币净资产</small></strong>${lead!==null?`<span class="winner-lead">领先第二名 ${fmt(lead)} 奶币</span>`:''}</section><div class="settlement-meta"><span>${MAPS[g.s.mapVersion].name}</span><span>${rows.length} 人 · 第 ${g.s.round} / ${g.s.maxRounds} 轮</span></div>${human?`<p class="personal-result">${human.winner?'恭喜你，登上奶家富豪榜首！':`你的本局排名：第 ${human.rank} 名${human.player.alive?'':' · 已破产退出'}`} · 拥有 ${human.lots} 块地产</p>`:''}<h3 class="settlement-heading">奶家资产榜 <small>点开奶伴查看资产明细</small></h3><div class="settlement-ranks">${rows.map(row=>{const p=row.player,c=g.char(p);return `<details class="result-entry ${p.human?'result-is-you':''}" ${p.human?'open':''}><summary aria-labelledby="result-rank${p.id} result-name${p.id} result-total${p.id}" aria-describedby="result-state${p.id}"><span class="result-place" id="result-rank${p.id}"><span class="sr-only">第</span>${row.rank}<span class="sr-only">名</span></span><span aria-hidden="true" class="result-face" style="background:${c.color}">${portrait(c.id)}</span><span class="result-name"><span id="result-name${p.id}">${c.name}</span>${p.human?'<b>你</b>':''}<small id="result-state${p.id}">${p.alive?row.winner?'本局冠军':row.lots+' 块地产':'已破产'}</small></span><strong id="result-total${p.id}">${fmt(row.assets.total)}<small>净资产 <span aria-hidden="true">▾</span></small></strong></summary>${assetDetails(row)}</details>`;}).join('')}</div><p class="settlement-rule">存活角色优先；同为存活或破产且净资产相同则并列。地产按购入与建筑名义成本估值，股票按结算时市价计价，交通工具按购入价计价；点券和手牌不计入净资产。</p><div class="button-grid result-actions"><button class="primary" data-act="newGame">再去旅行一次</button><button class="secondary" data-act="viewBoard">回看小岛</button><button class="secondary" data-act="export">保存本局存档</button></div></div>`;
}
